INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b0-74fd-8920-c61eb417d938', NULL, 'first_touch_audit', 'First touch, audit-led', 'first_touch', 'website_redesign', 'en', 1, ARRAY['A few notes on {{business.name}}’s website', '{{business.name}}: a quick look at your website', 'Some ideas for {{business.name}}’s website']::text[], '{{#if contact.firstName}}Hello {{contact.firstName}},{{else}}Hello,{{/if}}

I’m {{sender.firstName}} from {{sender.agencyName}}, a small studio working with local businesses{{#if business.locality}} in {{business.locality}}{{/if}}. I recently spent some time on {{business.name}}’s website and took a few notes.

{{#if audit.topFindings}}What stood out:

{{#each audit.topFindings}}- {{this}}
{{/each}}
{{/if}}{{#if audit.mobileScore}}On a phone, the site currently scores {{audit.mobileScore}} out of 100 in our test, and phones are where many people first look.

{{/if}}None of this is unusual, and all of it is fixable. If it would be useful, I can send over a few concrete ideas for {{offer.label}}, or walk you through them in a 10-minute call. Just let me know which you would prefer.
{{#if contact.isGeneric}}
If someone else looks after the website at {{business.name}}, please feel free to forward this.
{{/if}}
