INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b1-7604-b80a-d9e4aff7b82e', NULL, 'first_touch_new_website', 'First touch, no existing website', 'first_touch', 'new_website', 'en', 1, ARRAY['A first website concept for {{business.name}}', '{{business.name}} online: a concept to look at', 'An idea for {{business.name}}']::text[], '{{#if contact.firstName}}Hello {{contact.firstName}},{{else}}Hello,{{/if}}

I’m {{sender.firstName}} from {{sender.agencyName}}, a small studio working with local businesses{{#if business.locality}} in {{business.locality}}{{/if}}. I could not find a website for {{business.name}}, so we took the liberty of sketching one.

{{#if reviews.topTheme}}Reading what customers say about you, one theme comes up: {{reviews.topTheme}}. A simple site could help with that.

{{/if}}Here is a concept of what {{offer.label}} for {{business.name}} could look like. It is a first draft, not a finished site, and it comes with no obligation:

{{preview.url}}

