INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b2-73b3-89a5-4a4d5774cd5d', NULL, 'first_touch_preview', 'First touch with preview', 'first_touch', 'website_redesign', 'en', 1, ARRAY['A website concept for {{business.name}}', 'An idea for {{business.name}}’s website', '{{business.name}}: a quick concept to look at']::text[], '{{#if contact.firstName}}Hello {{contact.firstName}},{{else}}Hello,{{/if}}

I’m {{sender.firstName}} from {{sender.agencyName}}, a small studio working with local businesses{{#if business.locality}} in {{business.locality}}{{/if}}. {{business.name}} caught my eye while I was looking at businesses in the area, and I spent some time on your current website.

{{#if audit.topFindings}}A few things stood out:

