INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b2-73b3-89a5-4f17c39dde2f', NULL, 'follow_up_1', 'Follow-up 1', 'follow_up', 'website_redesign', 'en', 1, ARRAY['Following up on {{business.name}}’s website', 'One more thought for {{business.name}}', '{{business.name}}: a quick follow-up']::text[], '{{#if contact.firstName}}Hello {{contact.firstName}},{{else}}Hello,{{/if}}

