INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b2-73b3-89a5-51798797614b', NULL, 'follow_up_2', 'Follow-up 2, closing the loop', 'breakup', 'website_redesign', 'en', 1, ARRAY['Closing the loop on {{business.name}}', 'Last note from me, {{business.name}}', '{{business.name}}: I’ll leave it here']::text[], '{{#if contact.firstName}}Hello {{contact.firstName}},{{else}}Hello,{{/if}}

