INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b2-73b3-89a5-542d44e826a6', NULL, 'reply_more_info', 'Reply to “tell me more”', 'reply', 'website_redesign', 'en', 1, ARRAY['More detail for {{business.name}}', 'What we would do for {{business.name}}', 'A bit more on the idea']::text[], '{{#if contact.firstName}}Hello {{contact.firstName}},{{else}}Hello,{{/if}}

Thank you for getting back to me. In short: we would start from how your customers find and contact {{business.name}} today, then design a site that makes the next step obvious on a phone as much as on a laptop. We take care of the design, the wording and the technical side.

To tailor this, one question: what would you most want a new site to do for you, more bookings, fewer phone calls, or something else?

Best regards,', ARRAY['business.name', 'contact.firstName']::text[], 'active', true, '[{"code":"too_long","severity":"warning","message":"86 words; keep it under 80","at":"body"}]'::jsonb) ON CONFLICT DO NOTHING;
