INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b2-73b3-89a5-58a8b0839754', NULL, 'reply_not_now', 'Reply to “not now”', 'reply', 'website_redesign', 'en', 1, ARRAY['Understood, {{business.name}}', 'Thanks for letting me know', 'Checking back later, if that suits you']::text[], '{{#if contact.firstName}}Hello {{contact.firstName}},{{else}}Hello,{{/if}}

Thank you for letting me know; I appreciate the straight answer. I understand this is not the moment, and I will not keep nudging.

