INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b3-721c-9115-7fc28cbea5ba', NULL, 'reply_referral', 'Reply to a referral', 'reply', 'website_redesign', 'en', 1, ARRAY['Thank you for the introduction', 'Thanks, I’ll reach out to them', '{{business.name}}: thank you for your help']::text[], '{{#if contact.firstName}}Hello {{contact.firstName}},{{else}}Hello,{{/if}}

Thank you for taking the time to point me to the right person; that helps a great deal. I will get in touch with them directly, mention that you passed my note along, and keep it short.

Have a good day, and my best to the team at {{business.name}}.

Best regards,', ARRAY['business.name', 'contact.firstName']::text[], 'active', true, '[]'::jsonb) ON CONFLICT DO NOTHING;
