INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b3-721c-9115-821631f71869', NULL, 'first_touch_audit', 'Première prise de contact, axée audit', 'first_touch', 'website_redesign', 'fr', 1, ARRAY['Quelques notes sur le site de {{business.name}}', '{{business.name}} : un regard sur votre site', 'Des pistes pour le site de {{business.name}}']::text[], '{{#if contact.firstName}}Bonjour {{contact.firstName}},{{else}}Bonjour,{{/if}}

Je suis {{sender.firstName}}, de {{sender.agencyName}}, un petit studio qui accompagne les commerces et entreprises locales{{#if business.locality}} à {{business.locality}}{{/if}}. J’ai récemment passé un moment sur le site de {{business.name}} et j’ai pris quelques notes.

{{#if audit.topFindings}}Ce qui ressort :

{{#each audit.topFindings}}- {{this}}
{{/each}}
{{/if}}{{#if audit.mobileScore}}Sur téléphone, le site obtient actuellement {{audit.mobileScore}} sur 100 à notre test, et c’est souvent là que l’on vous découvre en premier.

{{/if}}Rien d’inhabituel, et tout cela se corrige. Si cela vous est utile, je peux vous envoyer quelques pistes concrètes pour {{offer.label}}, ou vous les présenter en dix minutes au téléphone. Dites-moi ce qui vous convient le mieux.
{{#if contact.isGeneric}}
Si quelqu’un d’autre s’occupe du site chez {{business.name}}, n’hésitez pas à lui transmettre ce message.
{{/if}}
Bien cordialement,', ARRAY['audit.mobileScore', 'audit.topFindings', 'business.locality', 'business.name', 'contact.firstName', 'contact.isGeneric', 'offer.label', 'sender.agencyName', 'sender.firstName']::text[], 'active', true, '[{"code":"too_long","severity":"warning","message":"136 words; keep it under 120","at":"body"}]'::jsonb) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b3-721c-9115-876041ab0327', NULL, 'first_touch_new_website', 'Première prise de contact, sans site existant', 'first_touch', 'new_website', 'fr', 1, ARRAY['Un premier site pour {{business.name}} ?', 'Une ébauche de site pour {{business.name}}', '{{business.name}} en ligne : une idée à découvrir']::text[], '{{#if contact.firstName}}Bonjour {{contact.firstName}},{{else}}Bonjour,{{/if}}

Je suis {{sender.firstName}}, de {{sender.agencyName}}, un petit studio qui accompagne les commerces et entreprises locales{{#if business.locality}} à {{business.locality}}{{/if}}. Je n’ai pas trouvé de site internet pour {{business.name}}, alors nous nous sommes permis d’en esquisser un.

{{#if reviews.topTheme}}En lisant ce que vos clients disent de vous, un thème revient : {{reviews.topTheme}}. Un site simple peut y répondre en partie.

{{/if}}Voici un aperçu de ce que pourrait donner {{offer.label}} pour {{business.name}}. C’est une première ébauche, pas un site terminé, et elle n’engage à rien :

{{preview.url}}

Si vous souhaitez voir où cela pourrait mener, dix minutes au téléphone suffisent. Une courte réponse me convient aussi.
{{#if contact.isGeneric}}
Si quelqu’un d’autre s’en occupe chez {{business.name}}, merci d’avance de bien vouloir lui transmettre ce message.
{{/if}}
Bien cordialement,', ARRAY['business.locality', 'business.name', 'contact.firstName', 'contact.isGeneric', 'offer.label', 'preview.url', 'reviews.topTheme', 'sender.agencyName', 'sender.firstName']::text[], 'active', true, '[{"code":"unguarded_optional","severity":"warning","message":"preview.url is optional: wrap it in {{#if preview.url}}","at":"preview.url"},{"code":"too_long","severity":"warning","message":"139 words; keep it under 120","at":"body"}]'::jsonb) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b3-721c-9115-8bccca3d191f', NULL, 'first_touch_preview', 'Première prise de contact avec aperçu', 'first_touch', 'website_redesign', 'fr', 1, ARRAY['Une idée de site pour {{business.name}}', '{{business.name}} : un aperçu de site à découvrir', 'Un concept de site pour {{business.name}}']::text[], '{{#if contact.firstName}}Bonjour {{contact.firstName}},{{else}}Bonjour,{{/if}}

Je suis {{sender.firstName}}, de {{sender.agencyName}}, un petit studio qui accompagne les commerces et entreprises locales{{#if business.locality}} à {{business.locality}}{{/if}}. En parcourant les établissements du secteur, {{business.name}} a retenu mon attention et j’ai pris le temps de regarder votre site actuel.

{{#if audit.topFindings}}Quelques points ressortent :

{{#each audit.topFindings}}- {{this}}
{{/each}}
{{/if}}Plutôt que de décrire ce que nous changerions, nous avons préparé un aperçu de ce que pourrait donner {{offer.label}} pour {{business.name}}. C’est une ébauche, pas un site terminé, et elle n’engage à rien :

{{preview.url}}

Si cela vous donne des idées, auriez-vous dix minutes pour en parler ? Une courte réponse me convient aussi.
{{#if contact.isGeneric}}
Si quelqu’un d’autre s’occupe du site chez {{business.name}}, merci d’avance de bien vouloir lui transmettre ce message.
{{/if}}
Bien cordialement,', ARRAY['audit.topFindings', 'business.locality', 'business.name', 'contact.firstName', 'contact.isGeneric', 'offer.label', 'preview.url', 'sender.agencyName', 'sender.firstName']::text[], 'active', true, '[{"code":"unguarded_optional","severity":"warning","message":"preview.url is optional: wrap it in {{#if preview.url}}","at":"preview.url"},{"code":"too_long","severity":"warning","message":"137 words; keep it under 120","at":"body"}]'::jsonb) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b3-721c-9115-8d36f5bb669f', NULL, 'follow_up_1', 'Relance 1', 'follow_up', 'website_redesign', 'fr', 1, ARRAY['Suite à mon message sur {{business.name}}', 'Un détail de plus pour {{business.name}}', '{{business.name}} : petite relance']::text[], '{{#if contact.firstName}}Bonjour {{contact.firstName}},{{else}}Bonjour,{{/if}}

Je vous ai écrit récemment au sujet du site de {{business.name}} et je voulais ajouter un élément.

{{#if preview.url}}L’aperçu que nous avons esquissé pour {{offer.label}} est toujours là si vous avez un instant : {{preview.url}}{{else}}{{#if audit.topFindings}}Un point que je n’avais pas mentionné : {{#each audit.topFindings}}{{this}}{{/each}}. C’est un détail, vite corrigé.{{else}}J’ai quelques pistes concrètes pour {{offer.label}} que je partagerais volontiers.{{/if}}{{/if}}

Pas besoin d’une longue réponse : un oui, un non ou un « pas maintenant » me suffit.

Bien cordialement,', ARRAY['audit.topFindings', 'business.name', 'contact.firstName', 'offer.label', 'preview.url']::text[], 'active', true, '[{"code":"too_long","severity":"warning","message":"94 words; keep it under 80","at":"body"}]'::jsonb) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b3-721c-9115-917bd5099566', NULL, 'follow_up_2', 'Relance 2, dernier message', 'breakup', 'website_redesign', 'fr', 1, ARRAY['Je clos le sujet, {{business.name}}', 'Dernier message de ma part', '{{business.name}} : je n’insiste pas']::text[], '{{#if contact.firstName}}Bonjour {{contact.firstName}},{{else}}Bonjour,{{/if}}

Sans réponse de votre part, j’en déduis que le moment n’est pas le bon, et c’est tout à fait compréhensible. Je ne vous relancerai pas après ce message.

{{#if preview.url}}L’aperçu préparé pour {{business.name}} reste en ligne{{#if preview.expiresAt}} jusqu’au {{preview.expiresAt}}{{/if}} si vous souhaitez y jeter un œil plus tard : {{preview.url}}

{{/if}}Si {{offer.label}} redevient une priorité un jour, ma porte reste ouverte. Je vous souhaite une belle saison.

Bien cordialement,', ARRAY['business.name', 'contact.firstName', 'offer.label', 'preview.expiresAt', 'preview.url']::text[], 'active', true, '[]'::jsonb) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b3-721c-9115-973c22bf9707', NULL, 'reply_more_info', 'Réponse à « en savoir plus »', 'reply', 'website_redesign', 'fr', 1, ARRAY['Plus de détails pour {{business.name}}', 'Ce que nous ferions pour {{business.name}}', 'Quelques précisions sur l’idée']::text[], '{{#if contact.firstName}}Bonjour {{contact.firstName}},{{else}}Bonjour,{{/if}}

Merci de votre retour. En résumé : nous partons de la façon dont vos clients trouvent et contactent {{business.name}} aujourd’hui, puis nous concevons un site qui rend l’étape suivante évidente, sur téléphone comme sur ordinateur. Nous prenons en charge la conception, les textes et la partie technique.

Pour ajuster tout cela, une question : qu’attendriez-vous en priorité d’un nouveau site, davantage de réservations, moins d’appels à gérer, ou autre chose ?

Bien cordialement,', ARRAY['business.name', 'contact.firstName']::text[], 'active', true, '[]'::jsonb) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b3-721c-9115-9ae10a0a2935', NULL, 'reply_not_now', 'Réponse à « pas maintenant »', 'reply', 'website_redesign', 'fr', 1, ARRAY['Bien noté, {{business.name}}', 'Merci pour votre réponse', 'Je reviens vers vous plus tard, si vous le souhaitez']::text[], '{{#if contact.firstName}}Bonjour {{contact.firstName}},{{else}}Bonjour,{{/if}}

Merci de m’avoir répondu, j’apprécie la franchise. Je comprends que ce ne soit pas le moment et je n’insisterai pas.

Verriez-vous un inconvénient à ce que je reprenne contact dans quelques mois ? Si vous préférez que je n’y revienne pas, dites-le-moi simplement et j’en resterai là.

Bonne continuation à {{business.name}}.

Bien cordialement,', ARRAY['business.name', 'contact.firstName']::text[], 'active', true, '[]'::jsonb) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b4-7092-bea0-7b6cec612257', NULL, 'reply_price', 'Réponse à une question de prix', 'reply', 'website_redesign', 'fr', 1, ARRAY['Votre question sur le tarif', 'Tarif pour le site de {{business.name}}', '{{business.name}} : vers un devis clair']::text[], '{{#if contact.firstName}}Bonjour {{contact.firstName}},{{else}}Bonjour,{{/if}}

Merci pour votre réponse, la question est légitime. Honnêtement, cela dépend du périmètre : le nombre de pages, la présence d’une réservation en ligne ou d’une boutique, les textes, les photos et les langues. Un site d’une page et une refonte complète sont deux projets très différents.

Plutôt que d’avancer un chiffre, pourrions-nous prendre quinze minutes au téléphone ? Je vous poserai quelques questions et vous enverrai ensuite un devis clair par écrit.

Bien cordialement,', ARRAY['business.name', 'contact.firstName']::text[], 'active', true, '[{"code":"too_long","severity":"warning","message":"82 words; keep it under 80","at":"body"}]'::jsonb) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "email_templates" ("id", "organization_id", "key", "name", "purpose", "offer", "locale", "version", "subject_variants", "body_md", "variables", "status", "seeded", "lint") VALUES ('01a149c7-82b4-7092-bea0-7eaa1b1dc4a1', NULL, 'reply_referral', 'Réponse à une mise en relation', 'reply', 'website_redesign', 'fr', 1, ARRAY['Merci pour la mise en relation', 'Merci, je contacte la bonne personne', '{{business.name}} : merci pour votre aide']::text[], '{{#if contact.firstName}}Bonjour {{contact.firstName}},{{else}}Bonjour,{{/if}}

